import{B as e,et as t,mt as n,tt as r}from"./chunks/framework.CxxritPY.js";var i=JSON.parse(`{"title":"디자인 시스템을 만든다고 AI 느낌이 사라질까","description":"디자인 시스템은 일관성을 주는 규칙일 뿐이다. 서비스마다 마주치는 뻔한 패턴의 피로감과 디자이너의 빈자리까지 채워주지는 못한다.","frontmatter":{"title":"디자인 시스템을 만든다고 AI 느낌이 사라질까","date":"2026-10-15T07:00+09:00","description":"디자인 시스템은 일관성을 주는 규칙일 뿐이다. 서비스마다 마주치는 뻔한 패턴의 피로감과 디자이너의 빈자리까지 채워주지는 못한다.","tags":["디자인 시스템","AI","프론트엔드"]},"headers":[],"relativePath":"posts/design-system-ai-slop.md","filePath":"posts/design-system-ai-slop.md","lastUpdated":1793451547000}`),a={name:`posts/design-system-ai-slop.md`};function o(e,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[r(`<h1 id="디자인-시스템을-만든다고-ai-느낌이-사라질까" tabindex="-1">디자인 시스템을 만든다고 AI 느낌이 사라질까 <a class="header-anchor" href="#디자인-시스템을-만든다고-ai-느낌이-사라질까" aria-label="Permalink to “디자인 시스템을 만든다고 AI 느낌이 사라질까”">​</a></h1><p><a href="https://news.hada.io/topic?id=35347" target="_blank" rel="noreferrer">「프론트엔드 ai티를 많이 줄이는 법」</a>에서는 디자인 시스템으로 일관성을 유지하면 AI 티가 나지 않는다고 말한다.</p><p>디자인 시스템은 일관성을 주는 규칙일 뿐이라서, 코딩 컨벤션을 지킨다고 좋은 코드가 보장되지 않는 것처럼 화면 스타일을 맞춘다고 디자인이 좋아지지는 않는다. 글쓰기에서 반복되는 AI 문체에 피로를 느끼게 되는 바와 같이, 서로 다른 웹 서비스에서 똑같은 배치와 장식을 마주치는 것이 내가 느끼는 AI 티다.</p><div class="info custom-block"><p class="custom-block-title">내 눈에는 여전히 Slop</p><p>개편 화면도 제 눈에는 여전히 Slop처럼 느껴졌어요. 화면이 달라진 것을 AI 티가 사라진 것으로 받아들이며 스스로 타협한 것처럼 보여요.</p></div><h2 id="디자인-스킬을-써본-결과" tabindex="-1">디자인 스킬을 써본 결과 <a class="header-anchor" href="#디자인-스킬을-써본-결과" aria-label="Permalink to “디자인 스킬을 써본 결과”">​</a></h2><p>나도 <a href="https://news.hada.io/topic?id=32321" target="_blank" rel="noreferrer">AI 티가 나지 않는 디자인 스킬로 소개된 Hallmark</a>를 설치했다가 <a href="https://news.hada.io/topic?id=27750" target="_blank" rel="noreferrer">Impeccable</a>로 대체해 보기도 했다. 오늘은 <a href="https://news.hada.io/topic?id=33664" target="_blank" rel="noreferrer">다이어그램 디자인 규칙을 담은 Diagram Design</a>을 추가했다. 배치와 연결선, 강조색에 규칙을 두는 스킬이다.</p><p>다이어그램이라면 관계와 흐름이 더 잘 읽히는지, 웹 화면이라면 필요한 정보를 쉽게 찾을 수 있는지 봐야 한다. 디자인 시스템은 유용하지만, 무엇을 강조하고 덜어낼지는 결국 전문 디자이너가 요청하고 검토해야 한다. 개발자가 에이전트에만 맡겨서는 원하는 수준의 완성도가 나오기 힘들다.</p><div class="info custom-block"><p class="custom-block-title">마케팅과 디자이너의 빈자리</p><p>얼마 전 <a href="https://www.eipgrid.com/ko/" target="_blank" rel="noreferrer">회사 홈페이지</a> 개편만 봐도 그래요. 마케팅과 디자이너 없이 도구에만 의존한 화면은 겉은 정돈되었을지 몰라도, 강조할 핵심이 빠져서 어색한 느낌이 아직도 남아있죠.</p></div><h2 id="어색함은-알아도-고치는-방법은-모른다" tabindex="-1">어색함은 알아도 고치는 방법은 모른다 <a class="header-anchor" href="#어색함은-알아도-고치는-방법은-모른다" aria-label="Permalink to “어색함은 알아도 고치는 방법은 모른다”">​</a></h2><p>디자인 감각이 부족한 나도 AI 티가 나는 화면의 어색함은 느낄 순 있다. 하지만 어떻게 바꿔야 다른 사람에게도 자연스러워 보이는지까지는 모른다. 전문 디자이너로 일해 본 경험이 없기 때문일 것 같다.</p><p>AI 에이전트에 디자인 스킬을 넣어도 내가 원하는 방향을 구체적으로 제시하기는 여전히 어렵다. 무엇이 마음에 들지 않는지 아는 것과, 어떻게 고쳐야 하는지 설명하는 것 사이에는 차이가 있다. 규칙을 더 넣었다는 이유로 그 차이가 해결됐다고 여기고 싶지는 않다.</p><h2 id="참고-자료" tabindex="-1">참고 자료 <a class="header-anchor" href="#참고-자료" aria-label="Permalink to “참고 자료”">​</a></h2><ul><li><a href="https://news.hada.io/topic?id=28861" target="_blank" rel="noreferrer">DESIGN.md — AI 코딩 도구를 위한 디자인 시스템 단일 파일 포맷</a></li><li><a href="https://news.hada.io/topic?id=32321" target="_blank" rel="noreferrer">Hallmark — AI 티가 안 나는 디자인 스킬</a></li><li><a href="https://news.hada.io/topic?id=33664" target="_blank" rel="noreferrer">Diagram Design — AI가 만드는 다이어그램에 디자인 규칙을 더하는 스킬</a></li><li><a href="https://news.hada.io/topic?id=27750" target="_blank" rel="noreferrer">Impeccable — AI 하네스가 더 디자인 잘하게 만들기</a></li></ul>`,13)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};